import 'package:flutter/material.dart'  import 'package:flutter_riverpod/flutter_riverpod.dart'  import '../api/api_client.dart'  import '../widgets/loading_widget.dart'  import '../widgets/empty_state.dart'    class InvoicesScreen extends ConsumerStatefulWidget {    const InvoicesScreen({super.key})      @override    ConsumerState<InvoicesScreen> createState() => _InvoicesScreenState()  }    class _InvoicesScreenState extends ConsumerState<InvoicesScreen> {    List<dynamic> _invoices = []    bool _isLoading = true    String _filterStatus = ''      @override    void initState() {      super.initState()      _loadInvoices()    }      Future<void> _loadInvoices() async {      try {        final invoices = await ApiClient().getInvoices()        if (mounted) setState(() { _invoices = invoices; _isLoading = false })      } catch (e) {        if (mounted) setState(() => _isLoading = false)      }    }      String _getStatusLabel(String status) {      final labels = {        'draft': 'Черновик',        'sent': 'Отправлен',        'paid': 'Оплачен',        'overdue': 'Просрочен',        'cancelled': 'Отменен',      }      return labels[status] ?? status    }      Color _getStatusColor(String status) {      final colors = {        'draft': Colors.grey,        'sent': Colors.blue,        'paid': Colors.green,        'overdue': Colors.red,        'cancelled': Colors.grey,      }      return colors[status] ?? Colors.grey    }      Future<void> _showAddInvoiceDialog() async {      final numberController = TextEditingController()      final amountController = TextEditingController()      final dateController = TextEditingController()        await showModalBottomSheet(        context: context,        isScrollControlled: true,        shape: const RoundedRectangleBorder(          borderRadius: BorderRadius.vertical(top: Radius.circular(20)),        ),        builder: (context) => Padding(          padding: EdgeInsets.only(            bottom: MediaQuery.of(context).viewInsets.bottom,            left: 20,            right: 20,            top: 20,          ),          child: Column(            mainAxisSize: MainAxisSize.min,            crossAxisAlignment: CrossAxisAlignment.stretch,            children: [              Row(                mainAxisAlignment: MainAxisAlignment.spaceBetween,                children: [                  const Text('Новый счет', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)),                  IconButton(                    icon: const Icon(Icons.close),                    onPressed: () => Navigator.pop(context),                  ),                ],              ),              const SizedBox(height: 16),              TextField(                controller: numberController,                decoration: InputDecoration(                  labelText: 'Номер счета *',                  prefixIcon: const Icon(Icons.receipt_outlined),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 12),              TextField(                controller: amountController,                keyboardType: TextInputType.number,                decoration: InputDecoration(                  labelText: 'Сумма (₽) *',                  prefixIcon: const Icon(Icons.currency_ruble),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 12),              TextField(                controller: dateController,                readOnly: true,                onTap: () async {                  final date = await showDatePicker(                    context: context,                    initialDate: DateTime.now().add(const Duration(days: 14)),                    firstDate: DateTime.now(),                    lastDate: DateTime.now().add(const Duration(days: 365)),                  )                  if (date != null) {                    dateController.text = '${date.day.toString().padLeft(2, '0')}.${date.month.toString().padLeft(2, '0')}.${date.year}'                  }                },                decoration: InputDecoration(                  labelText: 'Срок оплаты',                  prefixIcon: const Icon(Icons.calendar_today),                  border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),                ),              ),              const SizedBox(height: 20),              ElevatedButton(                onPressed: () async {                  if (numberController.text.isEmpty || amountController.text.isEmpty) return                  try {                    await ApiClient().createInvoice({                      'invoice_number': numberController.text,                      'total_amount': double.parse(amountController.text),                      'due_date': dateController.text,                    })                    if (mounted) {                      Navigator.pop(context)                      _loadInvoices()                      ScaffoldMessenger.of(context).showSnackBar(                        const SnackBar(content: Text('Счет создан')),                      )                    }                  } catch (e) {                    ScaffoldMessenger.of(context).showSnackBar(                      SnackBar(content: Text('Ошибка: $e')),                    )                  }                },                style: ElevatedButton.styleFrom(                  padding: const EdgeInsets.symmetric(vertical: 16),                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),                ),                child: const Text('Создать счет', style: TextStyle(fontSize: 16)),              ),              const SizedBox(height: 20),            ],          ),        ),      )    }      @override    Widget build(BuildContext context) {      final filtered = _filterStatus.isEmpty          ? _invoices          : _invoices.where((i) => i['status'] == _filterStatus).toList()        final totalPaid = _invoices        .where((i) => i['status'] == 'paid')        .fold<double>(0, (sum, i) => sum + ((i['total_amount'] ?? 0) as num).toDouble())        return Scaffold(        appBar: AppBar(          title: const Text('Счета'),          actions: [            IconButton(              icon: const Icon(Icons.add),              onPressed: _showAddInvoiceDialog,            ),          ],        ),        body: _isLoading            ? const LoadingWidget()            : Column(                children: [                  // Stats                  Container(                    padding: const EdgeInsets.all(16),                    child: Row(                      children: [                        _StatItem(                          label: 'Оплачено',                          value: '${_invoices.where((i) => i['status'] == 'paid').length}',                          color: Colors.green,                        ),                        _StatItem(                          label: 'Просрочено',                          value: '${_invoices.where((i) => i['status'] == 'overdue').length}',                          color: Colors.red,                        ),                        _StatItem(                          label: 'Всего',                          value: '${totalPaid.toStringAsFixed(0)} ₽',                          color: Colors.blue,                        ),                      ],                    ),                  ),                    // Filter chips                  Container(                    height: 50,                    padding: const EdgeInsets.symmetric(horizontal: 16),                    child: ListView(                      scrollDirection: Axis.horizontal,                      children: [                        _FilterChip(                          label: 'Все',                          isSelected: _filterStatus.isEmpty,                          onTap: () => setState(() => _filterStatus = ''),                        ),                        _FilterChip(                          label: 'Черновики',                          isSelected: _filterStatus == 'draft',                          onTap: () => setState(() => _filterStatus = 'draft'),                        ),                        _FilterChip(                          label: 'Отправлены',                          isSelected: _filterStatus == 'sent',                          onTap: () => setState(() => _filterStatus = 'sent'),                        ),                        _FilterChip(                          label: 'Оплачены',                          isSelected: _filterStatus == 'paid',                          onTap: () => setState(() => _filterStatus = 'paid'),                        ),                        _FilterChip(                          label: 'Просрочены',                          isSelected: _filterStatus == 'overdue',                          onTap: () => setState(() => _filterStatus = 'overdue'),                        ),                      ],                    ),                  ),                    // List                  Expanded(                    child: filtered.isEmpty                        ? const EmptyState(                            icon: Icons.receipt_outlined,                            title: 'Нет счетов',                            subtitle: 'Создайте первый счет',                          )                        : RefreshIndicator(                            onRefresh: _loadInvoices,                            child: ListView.builder(                              padding: const EdgeInsets.all(16),                              itemCount: filtered.length,                              itemBuilder: (context, index) {                                final inv = filtered[index]                                return Card(                                  margin: const EdgeInsets.only(bottom: 12),                                  child: ListTile(                                    leading: Container(                                      padding: const EdgeInsets.all(10),                                      decoration: BoxDecoration(                                        color: _getStatusColor(inv['status']).withOpacity(0.1),                                        borderRadius: BorderRadius.circular(10),                                      ),                                      child: Icon(                                        Icons.receipt,                                        color: _getStatusColor(inv['status']),                                        size: 20,                                      ),                                    ),                                    title: Text(                                      inv['invoice_number'] ?? 'Без номера',                                      style: const TextStyle(fontWeight: FontWeight.w600),                                    ),                                    subtitle: Text(                                      '${(inv['total_amount'] ?? 0).toString()} ₽',                                      style: TextStyle(                                        color: Theme.of(context).colorScheme.primary,                                        fontWeight: FontWeight.bold,                                      ),                                    ),                                    trailing: Container(                                      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),                                      decoration: BoxDecoration(                                        color: _getStatusColor(inv['status']).withOpacity(0.1),                                        borderRadius: BorderRadius.circular(20),                                      ),                                      child: Text(                                        _getStatusLabel(inv['status']),                                        style: TextStyle(                                          fontSize: 11,                                          color: _getStatusColor(inv['status']),                                          fontWeight: FontWeight.w500,                                        ),                                      ),                                    ),                                  ),                                )                              },                            ),                          ),                  ),                ],              ),      )    }  }    class _StatItem extends StatelessWidget {    final String label    final String value    final Color color      const _StatItem({required this.label, required this.value, required this.color})      @override    Widget build(BuildContext context) {      return Expanded(        child: Container(          padding: const EdgeInsets.symmetric(vertical: 12),          margin: const EdgeInsets.symmetric(horizontal: 4),          decoration: BoxDecoration(            color: color.withOpacity(0.1),            borderRadius: BorderRadius.circular(12),          ),          child: Column(            children: [              Text(                value,                style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold, color: color),              ),              const SizedBox(height: 4),              Text(                label,                style: TextStyle(fontSize: 11, color: Colors.grey[600]),              ),            ],          ),        ),      )    }  }    class _FilterChip extends StatelessWidget {    final String label    final bool isSelected    final VoidCallback onTap      const _FilterChip({required this.label, required this.isSelected, required this.onTap})      @override    Widget build(BuildContext context) {      return Padding(        padding: const EdgeInsets.only(right: 8),        child: ChoiceChip(          label: Text(label),          selected: isSelected,          selectedColor: Theme.of(context).colorScheme.primary,          backgroundColor: Colors.grey[200],          onSelected: (_) => onTap(),        ),      )    }  }